-- Toruni persistent audit schema. IDs are generated by the application.
-- Financial values and score totals use exact PostgreSQL numeric types.

CREATE TABLE rounds (
  id uuid PRIMARY KEY,
  market text NOT NULL CHECK (market = 'BTC-USD'),
  status text NOT NULL CHECK (status IN ('lobby', 'active', 'settling', 'review_required', 'completed')),
  lobby_opened_at timestamptz NOT NULL,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  settlement_deadline timestamptz NOT NULL,
  scoring_version text NOT NULL,
  rules_json jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (starts_at > lobby_opened_at),
  CHECK (ends_at > starts_at),
  CHECK (settlement_deadline >= ends_at)
);

CREATE UNIQUE INDEX one_live_round ON rounds ((true))
  WHERE status IN ('lobby', 'active', 'settling', 'review_required');

CREATE TABLE app_sessions (
  session_hash text PRIMARY KEY CHECK (session_hash ~ '^[0-9a-f]{64}$'),
  csrf_hash text NOT NULL CHECK (csrf_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL CHECK (expires_at > created_at)
);

CREATE TABLE participants (
  id uuid PRIMARY KEY,
  round_id uuid NOT NULL REFERENCES rounds(id),
  account_id text,
  session_hash text NOT NULL REFERENCES app_sessions(session_hash),
  claimed_account_id text NOT NULL,
  display_name text,
  verification_state text NOT NULL CHECK (verification_state IN ('unverified', 'verified', 'review_required')),
  joined_at timestamptz NOT NULL,
  UNIQUE (round_id, session_hash),
  UNIQUE (round_id, id)
);

CREATE UNIQUE INDEX one_account_per_round ON participants (round_id, account_id)
  WHERE account_id IS NOT NULL;

CREATE TABLE quote_intents (
  id uuid PRIMARY KEY,
  participant_id uuid NOT NULL REFERENCES participants(id),
  round_id uuid NOT NULL REFERENCES rounds(id),
  side text NOT NULL CHECK (side IN ('buy', 'sell')),
  client_order_id text NOT NULL UNIQUE,
  sequence integer NOT NULL CHECK (sequence > 0),
  status text NOT NULL CHECK (status IN ('issued', 'submitted', 'observed', 'terminal', 'unknown')),
  created_at timestamptz NOT NULL,
  first_open_observed_at timestamptz,
  last_verified_at timestamptz,
  UNIQUE (participant_id, round_id, side, sequence),
  UNIQUE (id, participant_id, round_id),
  FOREIGN KEY (round_id, participant_id) REFERENCES participants(round_id, id)
);

CREATE TABLE order_observations (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  intent_id uuid NOT NULL REFERENCES quote_intents(id),
  participant_id uuid NOT NULL REFERENCES participants(id),
  round_id uuid NOT NULL REFERENCES rounds(id),
  observed_at timestamptz NOT NULL,
  exchange_event_at timestamptz,
  exchange_status text NOT NULL,
  exchange_order_id text,
  price numeric NOT NULL CHECK (price > 0),
  original_qty numeric NOT NULL CHECK (original_qty > 0),
  filled_qty numeric NOT NULL CHECK (filled_qty >= 0),
  post_only boolean NOT NULL,
  raw_digest text,
  error_code text,
  FOREIGN KEY (intent_id, participant_id, round_id)
    REFERENCES quote_intents(id, participant_id, round_id)
);

CREATE INDEX order_observations_by_intent_time
  ON order_observations (intent_id, observed_at DESC);

CREATE TABLE market_observations (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  round_id uuid NOT NULL REFERENCES rounds(id),
  observed_at timestamptz NOT NULL,
  exchange_event_at timestamptz,
  mark numeric CHECK (mark > 0),
  source text NOT NULL,
  data_status text NOT NULL CHECK (data_status IN ('healthy', 'stale', 'unavailable', 'invalid')),
  source_event_id text
);

CREATE INDEX market_observations_by_round_time
  ON market_observations (round_id, observed_at);

CREATE TABLE risk_observations (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  round_id uuid NOT NULL REFERENCES rounds(id),
  participant_id uuid NOT NULL REFERENCES participants(id),
  observed_at timestamptz NOT NULL,
  absolute_exposure numeric NOT NULL CHECK (absolute_exposure >= 0),
  available_collateral numeric NOT NULL,
  source text NOT NULL,
  FOREIGN KEY (round_id, participant_id) REFERENCES participants(round_id, id)
);

CREATE TABLE score_samples (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  round_id uuid NOT NULL REFERENCES rounds(id),
  participant_id uuid NOT NULL REFERENCES participants(id),
  sampled_at timestamptz NOT NULL,
  delta_scaled numeric(38, 0) NOT NULL CHECK (delta_scaled >= 0),
  points_per_minute_scaled numeric(38, 0) NOT NULL CHECK (points_per_minute_scaled >= 0),
  bid_intent_id uuid REFERENCES quote_intents(id),
  ask_intent_id uuid REFERENCES quote_intents(id),
  bid_bps numeric,
  ask_bps numeric,
  bid_quality_scaled numeric(13, 0) NOT NULL CHECK (bid_quality_scaled BETWEEN 0 AND 1000000000000),
  ask_quality_scaled numeric(13, 0) NOT NULL CHECK (ask_quality_scaled BETWEEN 0 AND 1000000000000),
  reason text NOT NULL,
  scoring_version text NOT NULL,
  UNIQUE (round_id, participant_id, sampled_at),
  FOREIGN KEY (bid_intent_id, participant_id, round_id)
    REFERENCES quote_intents(id, participant_id, round_id),
  FOREIGN KEY (ask_intent_id, participant_id, round_id)
    REFERENCES quote_intents(id, participant_id, round_id),
  FOREIGN KEY (round_id, participant_id)
    REFERENCES participants(round_id, id) DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE round_results (
  round_id uuid NOT NULL REFERENCES rounds(id),
  participant_id uuid NOT NULL REFERENCES participants(id),
  total_scaled numeric(38, 0) NOT NULL CHECK (total_scaled >= 0),
  score_version text NOT NULL,
  verified_seconds numeric NOT NULL CHECK (verified_seconds >= 0),
  unscored_seconds numeric NOT NULL CHECK (unscored_seconds >= 0),
  cleanup_state text NOT NULL CHECK (cleanup_state IN ('verified', 'unresolved', 'unknown')),
  finalized_at timestamptz NOT NULL,
  PRIMARY KEY (round_id, participant_id),
  FOREIGN KEY (round_id, participant_id)
    REFERENCES participants(round_id, id) DEFERRABLE INITIALLY IMMEDIATE
);
